function analyticsRecords(context=analyticsContext,index=1){if(!context)return;analyticsContext=context;const rows=analyticsRows(context),pages=Math.max(1,Math.ceil(rows.length/12));analyticsPage=Math.max(1,Math.min(index,pages));const title=context.type==='period'?'Passed assessments':'Assessment outcomes · '+context.outcome,subtitle=context.type==='period'?dateLabel(context.start)+(context.start===context.end?'':' – '+dateLabel(context.end)):'Selected reporting period through '+dateLabel(today);openModal(title,`${subtitle} · ${rows.length} records · ${filters.venue} · ${filters.level}`,rows.length?table(['STUDENT','SKILL','DATE','OUTCOME',''],rows.slice((analyticsPage-1)*12,analyticsPage*12).map(a=>`<tr><td><button class="text-button" data-action="profile:${a.student}">${esc(studentName(a.student))}</button></td><td>${esc(a.skillName||skillName(a.skill))}</td><td>${dateLabel(a.date)}</td><td>${pill(a.outcome,a.outcome==='Passed'?'':'amber')}</td><td>${button('Details','assessment-detail:'+a.id,'small')}</td></tr>`))+`<div class="table-bottom analytics-pagination"><span>${rows.length} records · Page ${analyticsPage} of ${pages}</span><div class="actions"><button class="button small" data-action="analytics-prev" ${analyticsPage===1?'disabled':''}>Previous</button><button class="button small" data-action="analytics-next" ${analyticsPage===pages?'disabled':''}>Next</button></div></div>`:empty('No assessments in this period','Choose another point or change the workspace filters.'),button('Close','close-modal'),true);}
