function fitnessHistory(index){if(!Number.isInteger(index)||!fitnessCategories[index])return;const student=scoped().find(s=>s.id===fitnessStudent&&s.track==='Intermediate');if(!student)return;const metric=fitnessCategories[index],rows=state.fitness.filter(r=>r.student===student.id).slice().sort((a,b)=>a.date.localeCompare(b.date)),values=rows.map(r=>r.values[index]),min=Math.min(...values),max=Math.max(...values),span=max-min||1,plotWidth=Math.max(560,rows.length*54),x=i=>rows.length===1?plotWidth/2:45+i*(plotWidth-85)/(rows.length-1),y=v=>140-(v-min)/span*110;openModal(metric.name+' history',`${student.name} · ${metric.unit}`,rows.length?`<div class="interactive-chart fitness-interactive"><div class="fitness-chart-scroll" style="--history-width:${plotWidth}px" tabindex="0" role="region" aria-label="Fitness history chart. Scroll horizontally to view every result."><svg class="chart" viewBox="0 0 ${plotWidth} 190" aria-label="${esc(metric.name)} recorded history"><line x1="40" y1="150" x2="${plotWidth-30}" y2="150" class="chart-grid"/><polyline points="${rows.map((r,i)=>`${x(i)},${y(r.values[index])}`).join(' ')}" fill="none" stroke="#026B33" stroke-width="2.5"/>${rows.map((r,i)=>`<g role="button" tabindex="0" class="chart-point" data-action="fitness-point" data-chart-readout="${esc(dateLabel(r.date)+': '+r.values[index]+' '+metric.unit)}" aria-label="${esc(dateLabel(r.date)+', '+r.values[index]+' '+metric.unit)}" aria-describedby="fitness-readout"><circle class="chart-hit" cx="${x(i)}" cy="${y(r.values[index])}" r="18"/><circle class="chart-dot" cx="${x(i)}" cy="${y(r.values[index])}" r="4.5"/><text class="point-value" x="${x(i)}" y="${y(r.values[index])-12}" text-anchor="middle">${r.values[index]}</text></g><text x="${x(i)}" y="176" text-anchor="middle">${new Date(r.date+'T00:00:00Z').toLocaleDateString('en-IN',{day:'numeric',month:'short',timeZone:'UTC'})}</text>`).join('')}</svg></div><output class="chart-readout" id="fitness-readout" aria-live="polite">Select, hover or focus a point to inspect its result. Scroll the chart to see more dates.</output></div><p class="inline-note" style="margin:14px 0">Recorded values only. No automatic performance score or ranking is applied.</p>`+table(['DATE',metric.name+' ('+metric.unit+')'],rows.map(r=>`<tr><td>${dateLabel(r.date)}</td><td>${r.values[index]}</td></tr>`)):empty('No results for this metric','Record fitness results to start a history.'),button('Close','close-modal'),true);modal.dataset.analytics='true';}
function updateChartReadout(target){const control=target.closest?.('[data-chart-readout]');if(!control)return;const host=control.closest('.interactive-chart'),output=host?.querySelector('.chart-readout');if(output){output.textContent=control.dataset.chartReadout;host.querySelectorAll('.chart-point').forEach(el=>el.classList.toggle('inspected',el===control));}}

function dashboard(){const ss=selectedStudents(),aa=selectedAssessments(),practice=needingPractice(),passed=aa.filter(a=>a.outcome==='Passed').length,pendingCount=ss.reduce((n,s)=>n+pending(s).length,0),isCoach=state.role!=='Management';return dashboardHero(ss,isCoach)+filterBar({date:true})+(isCoach?notice(`${state.role==='Head Coach'?'Head coach view: the complete journey of your assigned students.':'Assistant coach view: Spark session group at Indiranagar. Overall progression remains under head coach review.'}`):'')+(isCoach?`<section class="card card-pad coach-scope"><div class="card-head" style="margin-bottom:0;align-items:center"><div><h2>Today on court · ${ss.filter(s=>state.attendance.some(a=>a.student===s.id&&a.date===today&&a.status==='Present')).length} / ${ss.length} present</h2><p class="subtext">Unique students across all sessions · ${dateLabel(today)} · ${ss.filter(s=>state.attendance.some(a=>a.student===s.id&&a.date===today)).length} students marked</p></div><div class="actions">${button('Student progress','goto:students','small')}${button('Open assessment','execute:','small')}${button('Access drills','goto:toolkit','small')}</div></div></section>`:'')+`<section class="stats">${stat(isCoach?'Assigned students':'Total students',ss.length,'students',`${ss.filter(s=>inRange(s.joined)).length} enrolled within selected period`)}${stat('Assessments completed',aa.length,'assessments',`<strong>${passed} passed</strong> in selected period`)}${stat('Pending assessments',pendingCount,'clock','Across scheduled assessment cycles')}${stat('Needs additional practice',new Set(practice.map(a=>a.student)).size,'fitness','Students with latest unsuccessful attempts')}</section><div class="dashboard-grid"><section class="card card-pad"><div class="card-head"><div><h2>Student progression</h2><p class="subtext">Successful skill assessments over time</p></div><div class="chart-legend"><span><span class="dot" style="background:#026B33"></span>Badges demonstrated</span></div></div>${progressionChart()}<div class="card-footer"><span>Skill completion is independent of level promotion</span><span>${passed} successful assessments</span></div></section><section class="card card-pad"><div class="card-head"><div><h2>Students by level</h2><p class="subtext">Grouped by skill, never by age</p></div>${icon('curriculum')}</div>${distribution()}<div class="card-footer"><span>4 levels · 16 beginner badges</span><a class="text-button" href="#curriculum">View curriculum →</a></div></section></div><div class="dashboard-grid"><section class="card"><div class="card-head" style="padding:23px 23px 0;margin-bottom:18px"><div><h2>A little more practice, a big difference.</h2><p class="subtext">Students who would benefit from focused coaching</p></div><button class="text-button" data-action="practice-list">View all →</button></div>${practice.length?table(['STUDENT','FOCUS SKILL','ATTEMPTS','NEXT STEP'],practice.slice(0,4).map(a=>{const s=state.students.find(s=>s.id===a.student),n=state.assessments.filter(x=>!x.baseline&&x.date<=today&&x.student===a.student&&x.skill===a.skill&&x.outcome==='Needs Practice').length;return `<tr><td>${person(s)}</td><td>${esc(skillName(a.skill))}</td><td>${pill(n+' needs practice',n>1?'red':'amber')}</td><td>${button('Review','execute:'+s.id+':'+a.skill,'small')}</td></tr>`;})):empty('Everyone is moving forward','No students require additional practice in this view.')}</section><section class="card card-pad"><div class="card-head"><div><h2>Assessment performance</h2><p class="subtext">Outcomes in the selected period</p></div>${icon('reports')}</div><div class="mini-stat-row"><div><strong>${aa.length?Math.round(passed/aa.length*100):0}%</strong><span>pass rate</span></div><div><strong>${aa.length}</strong><span>assessments recorded</span></div></div>${outcomeBar('Passed',aa,'var(--green)')}${outcomeBar('Needs Practice',aa,'#b87e39')}<p class="inline-note">Track assessment outcomes and plan focused reassessments.</p></section></div><div class="dashboard-grid"><section class="card card-pad"><div class="card-head"><div><h2>Across the academy</h2><p class="subtext">Venue distribution & recent activity</p></div>${canManage()?'<a class="text-button" href="#reports">Open reports →</a>':'<a class="text-button" href="#students">View students →</a>'}</div><div class="form-grid"><div>${venueBars()}</div><div>${visibleActivities({filtered:true}).filter(a=>inRange(a.date)).slice(0,3).map(a=>`<div class="activity-row"><span class="activity-marker">${icon(a.type==='badge'?'badge':'clock')}</span><div>${esc(a.text)}<small>${dateLabel(a.date)}</small></div></div>`).join('')||'<p class="subtext">No recent activity in this period.</p>'}</div></div></section><section class="card card-pad session-card"><div class="eyebrow">ON COURT, TODAY</div><h2>Make every session count.</h2><p class="subtext">Attendance, focused drills, and observations.<br>One connected coaching workflow.</p><div class="court"><span></span></div><div class="actions">${button('Open daily session','goto:attendance','','arrow')}${isCoach?button('Access drills','goto:toolkit','small'):''}</div></section></div>`;}
function students(){let ss=selectedStudents().filter(s=>(s.name+' '+s.id).toLowerCase().includes(studentSearch.trim().toLowerCase()));ss.sort((a,b)=>studentSort==='progress'?progress(b)-progress(a):studentSort==='level'?levels.indexOf(a.level)-levels.indexOf(b.level):a.name.localeCompare(b.name));const maxPage=Math.max(1,Math.ceil(ss.length/8));studentPage=Math.min(studentPage,maxPage);return head('Students','Every player has a different starting point. Give each one a clear path.',canManage()?button('Add student','student-add','primary','plus'):'')+filterBar({search:true})+`<section class="card"><div class="card-head" style="padding:20px 20px 0"><div><h2>Student directory <span class="pill neutral">${ss.length}</span></h2><p class="subtext">Student profiles and training progress</p></div><select id="student-sort" class="attendance-select" aria-label="Sort students"><option value="name" ${studentSort==='name'?'selected':''}>Name A–Z</option><option value="progress" ${studentSort==='progress'?'selected':''}>Most badges</option><option value="level" ${studentSort==='level'?'selected':''}>Curriculum level</option></select></div>${ss.length?table(['STUDENT','VENUE / HEAD COACH','LEVEL','BADGES','PENDING','PROGRESS',''],ss.slice((studentPage-1)*8,studentPage*8).map(s=>`<tr><td>${person(s)}</td><td>${esc(s.venue)}<small style="display:block;color:var(--muted);font-size:10px;margin-top:5px">${coachName(s.coach)}</small></td><td>${pill(s.level)} ${s.track==='Intermediate'?pill('Intermediate','neutral'):''}</td><td>${s.badges.length} / 16</td><td>${pending(s).length}</td><td><button class="table-progress progress-profile" data-action="profile:${s.id}" aria-label="Open ${esc(s.name)} progression, ${s.badges.length} of 16 skill badges, ${progress(s)} percent"><span class="progress-track"><span style="width:${progress(s)}%"></span></span><span>${progress(s)}% ↗</span></button></td><td><button class="icon-button" data-action="profile:${s.id}" aria-label="Open ${esc(s.name)}">${icon('chevron')}</button></td></tr>`)):empty()}<div class="table-bottom"><span>Showing ${ss.length?((studentPage-1)*8+1):0}–${Math.min(studentPage*8,ss.length)} of ${ss.length} students</span><div class="actions"><button class="button small" data-action="page-prev" ${studentPage===1?'disabled':''}>Previous</button><span>${studentPage} / ${maxPage}</span><button class="button small" data-action="page-next" ${studentPage===maxPage?'disabled':''}>Next</button></div></div></section>`;}
const levelClass=level=>levels.includes(level)?level.toLowerCase():'spark';
function sportMark(kind='shuttle'){return kind==='racket'?`<svg viewBox="0 0 64 64" aria-hidden="true"><ellipse cx="37" cy="24" rx="15" ry="20" transform="rotate(35 37 24)"/><path d="M25 40 9 59M20 45l5 5M24 13l25 18M20 23l24 17M30 6l-9 30M40 8 25 42M49 15 35 43"/></svg>`:`<svg viewBox="0 0 64 64" aria-hidden="true"><path d="m16 12 33 6-8 32-7 6-8-2-5-7Z M16 12l18 32m1-29 1 29m13-26L38 46M22 42l19 5"/><path d="M23 48c0 11 15 15 18 2"/></svg>`;}
function emblem(level,complete=false,large=false){return `<span class="collectible ${levelClass(level)} ${complete?'is-earned':''} ${large?'large':''}" aria-hidden="true"><span class="emblem-core">${sportMark(level==='Champ'?'racket':'shuttle')}</span><span class="emblem-star">${complete?'★':'✦'}</span></span>`;}
function levelArtwork(level,large=false){const name=levels.includes(level)?level:'Spark';return `<span class="level-artwork ${levelClass(name)} ${large?'large':''}"><img src="${name}.png" alt="${name} collection artwork — Padukone School of Badminton" width="436" height="424" loading="lazy" decoding="async"></span>`;}
function trainingPhoto(){return `<div class="training-photo"><img src="assets/badminton-training.jpg" alt="A young badminton player practising with a coach on an indoor court" width="1672" height="941" fetchpriority="high" decoding="async"><span class="training-photo-caption">On-court learning</span></div>`;}
function courtArt(){return `<div class="court-art" aria-hidden="true"><div class="court-lines"><i></i><b></b><span></span></div><div class="flying-shuttle">${sportMark()}</div><div class="court-caption">PLAY. LEARN. RISE.</div></div>`;}
function dashboardHero(ss,isCoach){const total=ss.reduce((n,s)=>n+s.badges.length,0);return `<section class="academy-hero ${isCoach?'coach-hero':''}"><div class="hero-copy">${partnershipLockup(true)}<div class="eyebrow">${isCoach?'YOUR COURT. THEIR NEXT CHAPTER.':'THE ACADEMY, IN MOTION'}</div><h1>${isCoach?'Great players start<br>with great practice.':'Small wins.<br>Extraordinary journeys.'}</h1><p>${isCoach?'Your players, their next challenges, and everything you need for a purposeful session.':'Every grip learned. Every rally extended. A clear view of the people making progress.'}</p><div class="hero-actions">${button(isCoach?'Start today’s session':'Explore your players',isCoach?'goto:attendance':'goto:students','primary','arrow')}${canManage()?button(isCoach?'Record assessment':'Add student',isCoach?'execute:':'student-add','','plus'):''}</div><div class="hero-footnote"><span class="live-dot"></span>${ss.length} players in view <span> / </span> ${total} skill badges collected</div></div>${trainingPhoto()}<span class="hero-edition">VISIST / GRASSROOTS</span></section>`;}
function playerHero(s){const current=state.skills.filter(k=>k.level===s.level),count=current.filter(k=>s.badges.includes(k.id)).length,next=focusSkill(s);return `<section class="player-stage ${levelClass(s.level)}"><div class="player-identity"><div class="eyebrow">PLAYER CARD <span> / ${s.id}</span></div><div class="player-name-row"><span class="player-monogram">${initials(s.name)}</span><div><h1>${esc(s.name)}</h1><p>${s.age} years · ${esc(s.venue)} · ${esc(s.track)}</p></div></div><div class="player-meta"><span>${pill(s.level)} Current level</span><span>Training with ${esc(coachName(s.coach))}</span></div><div class="hero-actions">${button('Assess a skill','execute:'+s.id,'primary','assessments')}${canManage()?button('Edit student','student-edit:'+s.id,'','edit'):''}</div></div><div class="player-achievement">${levelArtwork(s.level,true)}<div class="achievement-caption"><span>${esc(s.level.toUpperCase())} COLLECTION ARTWORK</span><strong>${count}<small> / 4</small></strong><p>${count===4?'Complete · Ready for coach review':'Skill badges collected'}</p></div></div><div class="player-next"><div><div class="eyebrow">${next?'YOUR NEXT CHALLENGE':'COLLECTION COMPLETE'}</div><h2>${esc(next?.name||'Ready for your coach’s review')}</h2><p>${esc(next?.description||'All skills in the current level are collected. Review your next step with your head coach.')}</p></div>${next?button('Practise this skill','drill:'+next.id,'small','arrow'):button('View collection','profile-tab:progression','small','badge')}</div></section>`;}
function skillJourney(student){return `<section class="journey-panel"><div class="journey-header"><div><div class="eyebrow">THE BIG PICTURE</div><h2>Your path to half-court ready.</h2></div><span>4 levels. Every skill counts.</span></div><div class="journey-track">${levels.map((l,i)=>{const ks=state.skills.filter(k=>k.level===l),count=student?ks.filter(k=>student.badges.includes(k.id)).length:0;return `<a class="journey-stop ${levelClass(l)} ${student?.level===l?'current':''}" href="#collection-${levelClass(l)}" data-action="collection:${levelClass(l)}" aria-label="Explore ${l} collection">${levelArtwork(l)}<div><span class="journey-index">0${i+1} ${student?.level===l?' / CURRENT LEVEL':''}</span><h3>${l}</h3><p>${student?count+' of 4 collected':['Discover the basics','Build your control','Find your technique','Own the half court'][i]}</p></div></a>`;}).join('')}</div><p class="journey-note">Earn skills at any level. Collect all four in one level for a main badge review.</p></section>`;}
function badgeMap(student){
 const latest=student?latestAttempts(state.assessments,{student:student.id,through:today}):[];
 return levels.map((l,i)=>{const skills=state.skills.filter(k=>k.level===l),count=student?skills.filter(k=>student.badges.includes(k.id)).length:0;return `<section class="curriculum-level collection-${levelClass(l)}" id="collection-${levelClass(l)}"><div class="collection-header"><div class="level-heading">${levelArtwork(l)}<span class="collection-index">0${i+1}</span><div><div class="eyebrow">${student?'YOUR COLLECTION':'THE SKILL COLLECTION'}</div><h2>${l}<span> / ${['The first spark','Control comes next','Technique takes shape','Half-court confidence'][i]}</span></h2></div></div><span class="collection-count">${student?`<strong>${count}</strong> / 4 collected`:'4 SKILL BADGES'}</span></div><p class="collection-guidance">${esc(levelGuidance[l])}${student&&count===4?' · All four collected: main badge ready for coach review.':''}</p><div class="skill-grid">${skills.map(k=>{
  const attempt=latest.find(a=>a.skill===k.id),done=student?.badges.includes(k.id),practice=attempt?.outcome==='Needs Practice',baseline=student?.baseline?.includes(k.id);
  const label=!student?'Explore skill':done?'Completed':practice?'Needs Practice':baseline?'Baseline demonstrated':'Ready to discover';
  return `<button class="skill-card ${done?'done':''} ${practice?'needs-practice':''}" data-action="skill:${k.id}${student?':'+student.id:''}"><div class="skill-topline"><span>SKILL ${String(k.id).padStart(2,'0')}</span><span>${done?'✓ EARNED':practice?'↻ PRACTISE':baseline?'BASELINE':'↗'}</span></div>${emblem(l,done)}<h3>${esc(k.name)}</h3><p>${esc(k.description)}</p><div class="skill-status">${pill(label,practice&&!done?'amber':done?'':'neutral')}<span aria-hidden="true">↗</span></div>${done&&practice?'<p class="inline-note">Reassessment needs practice</p>':''}</button>`;
 }).join('')}</div></section>`;}).join('');
}
function studentProfile(){const s=state.students.find(s=>s.id===profileId);if(!s||!scoped().some(x=>x.id===s.id)){profileId='';return students();}const aa=state.assessments.filter(a=>a.student===s.id).reverse().sort((a,b)=>b.date.localeCompare(a.date));return `<button class="text-button profile-back" data-action="students-back">← All players</button>${playerHero(s)}<section class="stats">${stat('Current level',s.level,'curriculum','Level progression requires coach review')}${stat('Skill badges',s.badges.length+' / 16','badge','Individual skills completed')}${stat('Pending modules',pending(s).length,'clock','Across fixed assessment cycles')}${stat('Attendance',state.attendance.filter(a=>a.student===s.id&&a.status==='Present').length,'attendance','Recorded sessions attended')}</section><div class="tabs">${['progression','information','assessments','attendance'].map(t=>`<button class="tab ${profileTab===t?'active':''}" data-action="profile-tab:${t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div>${profileTab==='progression'?skillJourney(s)+notice('Individual badges can be completed at any level. A badge award does not promote the student. Collect all four skill badges within the same level for a main badge review by the head coach.')+studentAttention(s)+badgeMap(s)+`<div class="card card-pad"><h2>Overall level review</h2><p class="subtext">${s.level} remains the current level. The reference requires all four skill badges from the same level for a main badge. Complete collections appear below for coach review; level changes remain manual.</p>${s.baseline?.length?`<p class="subtext" style="margin-top:12px">Day Zero demonstrated abilities: ${esc(s.baseline.map(skillName).join(', '))}. These remain baseline evidence for coach review.</p>`:''}</div>`:profileTab==='information'?`<div class="split"><section class="card card-pad"><h2>Personal information</h2><dl class="detail-list"><div><dt>Student ID</dt><dd>${s.id}</dd></div><div><dt>Age</dt><dd>${s.age} years</dd></div><div><dt>Guardian email</dt><dd>${esc(s.email)}</dd></div><div><dt>Guardian phone</dt><dd>${esc(s.phone)}</dd></div><div><dt>Joined</dt><dd>${dateLabel(s.joined)}</dd></div><div><dt>Training track</dt><dd>${s.track}</dd></div></dl></section><section class="card card-pad"><h2>Coaching team</h2><div class="activity-row"><span class="avatar">${initials(coachName(s.coach))}</span><div>${coachName(s.coach)}<small>Head Coach · Overall student journey</small></div></div><p class="inline-note">Students are grouped by demonstrated skill rather than age. Tournament results do not automatically change curriculum progression.</p></section></div>`:profileTab==='assessments'?`<section class="card">${assessmentTable(aa)}</section>`:`<section class="card">${state.attendance.some(a=>a.student===s.id)?table(['DATE','SESSION','STATUS','OBSERVATIONS'],state.attendance.filter(a=>a.student===s.id).sort((a,b)=>b.date.localeCompare(a.date)).map(a=>`<tr><td>${dateLabel(a.date)}</td><td>${esc(a.session)}</td><td>${pill(a.status,a.status==='Present'?'':'amber')}</td><td style="white-space:normal;max-width:300px">${esc(a.notes)||'—'}</td></tr>`)):empty('No session records','Attendance will appear after a daily session is saved.')}</section>`}`;}
function curriculum(){return `<section class="curriculum-hero"><div>${partnershipLockup(true)}<div class="eyebrow">THE VISIST SKILL JOURNEY</div><h1>First grip.<br>Next great player.</h1><p>Sixteen skills to discover. Four collections to build.<br>A little better, every time you step on court.</p></div><div class="curriculum-trophy">${levelArtwork('Champ',true)}<span>FROM FIRST GRIP TO<br>HALF-COURT READY</span></div></section>`+skillJourney()+notice('Earn individual skill badges at any level. Collect all four in one level for a main badge review with your head coach.')+badgeMap();}
function assessmentTable(aa){const max=Math.max(1,Math.ceil(aa.length/12));assessmentPage=Math.max(1,Math.min(assessmentPage,max));const visible=aa.slice((assessmentPage-1)*12,assessmentPage*12);return aa.length?table(['STUDENT','SKILL','DATE','OUTCOME','COACH / REMARKS',''],visible.map(a=>`<tr><td><button class="text-button" data-action="profile:${a.student}">${esc(studentName(a.student))}</button>${a.baseline?'<br>'+pill('Day Zero','neutral'):''}</td><td>${esc(a.skillName||skillName(a.skill))}</td><td>${dateLabel(a.date)}</td><td>${pill(a.outcome,a.outcome==='Passed'?'':'amber')}</td><td style="white-space:normal;max-width:260px"><small>${coachName(a.coach)}</small><p class="subtext">${esc(a.remarks)||'No remarks'}</p></td><td>${button('Details','assessment-detail:'+a.id,'small')}</td></tr>`))+`<div class="table-bottom"><span>Showing ${(assessmentPage-1)*12+1}–${Math.min(assessmentPage*12,aa.length)} of ${aa.length} records</span><div class="actions"><button class="button small" data-action="history-prev" ${assessmentPage===1?'disabled':''}>Previous records</button><span>${assessmentPage} / ${max}</span><button class="button small" data-action="history-next" ${assessmentPage===max?'disabled':''}>Next records</button></div></div>`:empty('No assessments in this view','Record an assessment or change the selected filters.');}
function cycleStatus(c){
 const ids=selectedStudents().map(s=>s.id),modules=c.assignments.filter(a=>ids.includes(a.student)).flatMap(a=>a.skills.map(skill=>({student:a.student,skill})));
 const done=modules.filter(m=>cycleOutcome(state,c,m.student,m.skill)).length;
 return modules.length&&done===modules.length?'Completed':done?'In progress':c.date<today?'Overdue':'Upcoming';
}
function assessments(){const ss=selectedStudents(),ids=ss.map(s=>s.id),aa=selectedAssessments(),practice=needingPractice();return head('Assessment is a step forward.','Plan fixed assessment dates, assign individual modules, and capture meaningful feedback.',(canManage()?button('Record assessment','execute:','','assessments')+button('Day Zero baseline','dayzero','','students')+button('Create cycle','cycle-add','primary','plus'):button('Record assessment','execute:','primary','assessments')))+filterBar({date:true})+`<section class="stats">${stat('Upcoming cycles',state.cycles.filter(c=>c.date>=today&&cycleStatus(c)!=='Completed'&&c.assignments.some(a=>ids.includes(a.student))).length,'attendance','Fixed dates · individual modules')}${stat('Completed assessments',aa.length,'assessments','Within the selected reporting period')}${stat('Pending modules',ss.reduce((n,s)=>n+pending(s).length,0),'clock','Student-specific assessment assignments')}${stat('Reassessment needed',practice.length,'fitness','Latest unsuccessful skill attempts')}</section><div class="tabs">${[['cycles','Assessment cycles'],['history','Assessment history'],['practice','Needs reassessment']].map(([id,label])=>`<button class="tab ${assessmentTab===id?'active':''}" data-action="assessment-tab:${id}">${label}</button>`).join('')}</div>${assessmentTab==='cycles'?`<section class="card">${state.cycles.filter(c=>c.assignments.some(a=>ids.includes(a.student))).map(c=>`<article class="cycle"><div class="cycle-date"><strong>${c.date.slice(8)}</strong><span>${new Date(c.date+'T12:00:00').toLocaleDateString('en-IN',{month:'short'}).toUpperCase()}</span></div><div class="cycle-content"><h3>${esc(c.name)}</h3><p>${dateLabel(c.date)} · ${c.assignments.filter(a=>ids.includes(a.student)).length} students · ${c.assignments.filter(a=>ids.includes(a.student)).reduce((n,a)=>n+a.skills.length,0)} assigned modules</p></div>${pill(cycleStatus(c),cycleStatus(c)==='Overdue'?'amber':cycleStatus(c)==='Completed'?'':'neutral')}${button('View cycle','cycle:'+c.id,'small')}</article>`).join('')||empty('No assessment cycles','Create a cycle with a fixed date and individual skill modules.')}</section>`:`<section class="card">${assessmentTable(assessmentTab==='practice'?practice:aa.slice().reverse().sort((a,b)=>b.date.localeCompare(a.date)))}</section>`}`;}
function coachPage(){return head('The people behind the progress.','A shared view of coaching assignments, session coverage, and student development.')+notice('Review coaching assignments, student coverage and upcoming assessments.')+`<div class="coach-grid">${coaches.filter(c=>canAdmin()||c.id===1||c.id===4).map(c=>{const ss=coachStudents(c);return `<section class="card card-pad"><span class="avatar">${initials(c.name)}</span><h2>${c.name}</h2><p>${c.role} · ${c.venue}</p><div class="mini-stat-row"><div><strong>${ss.length}</strong><span>${c.role==='Head Coach'?'assigned students':'venue students'}</span></div><div><strong>${ss.reduce((n,s)=>n+pending(s).length,0)}</strong><span>pending modules</span></div></div><p>${c.role==='Head Coach'?'Responsible for the complete student journey and foundational progression review.':'Supports session delivery, drills, attendance, and assessment observations.'}</p><div style="margin-top:18px">${button('View assignments','coach:'+c.id,'small','students')}</div></section>`;}).join('')}</div>`;}
function attendanceStudents(){return scoped().filter(s=>s.venue===attendanceVenue);}
function attendanceRecord(s){
 const draft=state.sessionDrafts[sessionKey()];
 if(draft&&s.id in draft.statuses)return {status:draft.statuses[s.id],notes:draft.notes};
 return state.attendance.find(a=>a.student===s.id&&a.date===attendanceDate&&a.session===attendanceSession);
}
function attendance(){const ss=attendanceStudents();return head('Start with who’s on court.','Mark attendance, focus the session, and capture observations in one place.',button('Save daily session','attendance-save','primary','check'),'DAILY COACHING')+`<div class="filters"><select id="attendance-venue" aria-label="Session venue">${venues.filter(v=>state.role==='Management'||v===venues[0]).map(v=>`<option ${v===attendanceVenue?'selected':''}>${v}</option>`).join('')}</select><select id="attendance-session" aria-label="Session"><option ${attendanceSession.startsWith('Evening')?'selected':''}>Evening · 4:30–6:00 PM</option><option ${attendanceSession.startsWith('Morning')?'selected':''}>Morning · 6:00–7:30 AM</option></select><input id="attendance-date" aria-label="Session date" type="date" max="${today}" value="${attendanceDate}"><span class="filter-count">${ss.length} assigned students</span></div><div class="split"><section class="card"><div class="card-head" style="padding:20px 20px 0"><div><h2>Session register</h2><p class="subtext">1. Mark attendance · 2. Review pending skills</p></div>${button('Mark all present','attendance-all','small')}</div>${ss.length?table(['STUDENT','LEVEL / FOCUS','ATTENDANCE'],ss.map(s=>`<tr><td>${person(s)}</td><td>${pill(s.level)}<small style="display:block;color:var(--muted);margin-top:6px">${esc(focusSkill(s)?.name||'Current-level skills complete · coach review')}</small></td><td><select class="attendance-select" data-attendance="${s.id}" aria-label="Attendance for ${esc(s.name)}">${['Unmarked','Present','Absent','Excused'].map(v=>`<option ${(attendanceRecord(s)?.status||'Unmarked')===v?'selected':''}>${v}</option>`).join('')}</select></td></tr>`)):empty('No students assigned','Choose a different venue.')}</section><div class="stack"><section class="card card-pad"><h2>3. Focused practice</h2><p class="subtext">Relevant drills for present students</p><div id="session-drills">${sessionDrills(ss.filter(s=>attendanceRecord(s)?.status==='Present'))}</div></section><section class="card card-pad"><h2>4. Session observations</h2><p class="subtext" style="margin-bottom:16px">Save coaching context alongside this register.</p><label class="field">Observations<textarea id="session-notes" maxlength="2000" placeholder="What went well? What needs another look?">${esc(state.sessionDrafts[sessionKey()]?.notes??ss.map(attendanceRecord).find(Boolean)?.notes??'')}</textarea></label><p id="session-dirty" class="inline-note" role="status">${state.sessionDrafts[sessionKey()]?'Unsaved draft · save to update dashboards.':'Register is up to date.'}</p><p class="inline-note" style="margin-top:12px">Notes are attached to each marked student’s attendance history.</p></section></div></div>`;}
function sessionDrills(ss){if(!ss.length)return '<p class="inline-note" style="margin-top:20px">Mark a student present to see relevant drills.</p>';const lv=[...new Set(ss.map(s=>s.level))];return lv.map(l=>{const k=state.skills.find(k=>k.level===l&&!ss.filter(s=>s.level===l).every(s=>s.badges.includes(k.id)))||state.skills.find(k=>k.level===l);return `<div class="activity-row"><span class="activity-marker">${icon('toolkit')}</span><div>${pill(l)}<h3 style="font-size:12px;margin-top:8px">${esc(k.drill)}</h3><p class="inline-note">${esc(k.name)} · Practice drill</p><button class="text-button" data-action="drill:${k.id}">Open instructions →</button></div></div>`;}).join('');}
function toolkit(){const kk=state.skills.filter(k=>(filters.level==='All levels'||k.level===filters.level)&&(toolSkill==='All skills'||k.id===+toolSkill));return head('Better practice starts here.','A coaching library that connects skills, drills, and assessment points.','', 'COACH TOOLKIT')+notice('Explore practice instructions and assessment points for each skill.')+`<div class="filters"><select data-filter="level" aria-label="Filter drills by level">${['All levels',...levels].map(l=>`<option ${filters.level===l?'selected':''}>${l}</option>`).join('')}</select><select id="tool-skill" aria-label="Filter by skill"><option>All skills</option>${state.skills.filter(k=>filters.level==='All levels'||k.level===filters.level).map(k=>`<option value="${k.id}" ${toolSkill==k.id?'selected':''}>${esc(k.name)}</option>`).join('')}</select><span class="filter-count">${kk.length} practice drills</span></div><div class="tool-grid">${kk.map(k=>`<article class="card tool-card"><div class="video-placeholder">${icon('play')}<span>VIDEO NOT ADDED</span></div><div class="card-pad">${pill(k.level)}<h3>${esc(k.drill)}</h3><p>${esc(k.name)}</p><p style="margin-top:12px">${esc(k.description)}</p><div style="margin-top:18px">${button('Open drill','drill:'+k.id,'small','','')}</div></div></article>`).join('')}</div>${!kk.length?empty():''}`;}
function fitness(){const ss=scoped().filter(s=>s.track==='Intermediate');if(!ss.some(s=>s.id===fitnessStudent))fitnessStudent=ss[0]?.id||'';const records=state.fitness.filter(f=>f.student===fitnessStudent).reverse().sort((a,b)=>b.date.localeCompare(a.date)),latest=records[0],previous=records[1];return head('A separate view of physical development.','Record intermediate fitness results and follow individual progress over time.',ss.length?button('Record results','fitness-add','primary','plus'):'','INTERMEDIATE FITNESS')+notice('Follow individual fitness development across recorded assessments. Beginner fitness is integrated into regular coaching.')+`<div class="filters"><select id="fitness-student" aria-label="Intermediate student" ${ss.length?'':'disabled'}>${ss.map(s=>`<option value="${s.id}" ${s.id===fitnessStudent?'selected':''}>${esc(s.name)} · ${s.id}</option>`).join('')}</select><span class="filter-count">${latest?'Latest record: '+dateLabel(latest.date):'No results recorded'}</span></div>${!ss.length?empty('No intermediate students in this role','Management can view all intermediate fitness records.'):latest?`<div class="fitness-grid">${fitnessCategories.map((c,i)=>`<button class="card fitness-metric" data-action="fitness-history:${i}" aria-label="View ${c.name} history for ${esc(studentName(fitnessStudent))}"><h3>${c.name}</h3><strong>${latest.values[i]}</strong><small>${c.unit}</small>${previous?`<p class="inline-note" style="margin-top:10px">Previous: ${previous.values[i]} · ${dateLabel(previous.date)}</p>`:''}<span class="metric-history-link">Explore history →</span></button>`).join('')}</div>`:empty('No fitness results yet','Record results to start a history.')}<section class="card" style="margin-top:24px"><div class="card-head" style="padding:20px 20px 0"><h2>Fitness history</h2></div>${records.length?table(['DATE',...fitnessCategories.map(c=>c.name)],records.map(f=>`<tr><td>${dateLabel(f.date)}</td>${f.values.map(v=>`<td>${v}</td>`).join('')}</tr>`)):empty('No historical results','Saved results will appear here.')}</section>`;}
function reports(){const ss=selectedStudents(),aa=selectedAssessments(),practice=needingPractice();return head('Progress, made visible.','A practical view of student development and academy operations.',button('Export CSV','export','primary','download'),'MANAGEMENT REPORTS')+filterBar({date:true})+`<section class="stats">${stat('Students in view',ss.length,'students',ss.filter(s=>inRange(s.joined)).length+' joined in selected period')}${stat('Badges completed',ss.reduce((n,s)=>n+s.badges.length,0),'badge','All-time badge stock for filtered students')}${stat('Assessment outcomes',aa.length,'assessments','Within selected date range')}${stat('Needs attention',new Set(practice.map(a=>a.student)).size,'fitness','Latest unsuccessful attempts in period')}</section><div class="split"><section class="card card-pad"><div class="card-head"><div><h2>Student progression</h2><p class="subtext">Successful assessments within the selected range</p></div></div>${progressionChart()}</section><section class="card card-pad"><h2>Venue summaries</h2>${venueReportRows()}</section></div><section class="card" style="margin-top:24px"><div class="card-head" style="padding:22px 22px 0"><div><h2>Coach operations</h2><p class="subtext">Assignment and activity counts · No coach rankings or scores</p></div></div>${table(['HEAD COACH','VENUE','ASSIGNED STUDENTS','ASSESSMENTS IN PERIOD','PENDING MODULES'],coaches.filter(c=>c.role==='Head Coach').map(c=>{const cs=ss.filter(s=>s.coach===c.id);return `<tr><td>${c.name}</td><td>${c.venue}</td><td>${cs.length}</td><td>${aa.filter(a=>a.coach===c.id).length}</td><td>${cs.reduce((n,s)=>n+pending(s).length,0)}</td></tr>`;}))}</section><section class="card" style="margin-top:24px"><div class="card-head" style="padding:22px 22px 0"><div><h2>Badge completion & attention</h2><p class="subtext">Individual skill achievements do not imply overall level promotion</p></div></div>${ss.length?table(['STUDENT','LEVEL','BADGES','ASSESSMENTS IN PERIOD','NEEDS PRACTICE'],ss.map(s=>`<tr><td>${person(s)}</td><td>${pill(s.level)}</td><td>${s.badges.length} / 16</td><td>${aa.filter(a=>a.student===s.id).length}</td><td>${practice.filter(a=>a.student===s.id).length}</td></tr>`)):empty()}</section>`;}
function settings(){return head('Workspace settings','Manage assessment settings, progression and workspace data.')+`<div class="split"><section class="card card-pad"><h2>Assessment rule</h2><p class="subtext" style="margin-bottom:20px">Choose the number of Yes responses required to pass an assessment.</p><form id="settings-form"><label class="field">Pass threshold<select name="threshold">${[1,2,3,4,5].map(n=>`<option value="${n}" ${state.settings.threshold===n?'selected':''}>${n} of 5 criteria answered Yes</option>`).join('')}</select><small>All five criteria must be answered. A passed regular assessment awards the individual badge. Day Zero results remain separate baseline evidence.</small></label><div style="margin-top:20px"><button class="button primary" type="submit">Save configuration</button></div></form></section><section class="card card-pad"><h2>Progression safeguards</h2><div class="activity-row">${icon('check')}<p>Four levels, four badges per level. Sixteen beginner badges in total.</p></div><div class="activity-row">${icon('check')}<p>Higher-level skills may be demonstrated individually. Level promotion is never automatic.</p></div><div class="activity-row">${icon('check')}<p>Foundational requirements and academy-approved progression rules require head coach review.</p></div><div class="activity-row">${icon('check')}<p>Tournament wins and Day Zero outcomes do not bypass foundational requirements.</p></div></section><section class="card card-pad"><h2>Workspace data</h2><p class="subtext">Manage the records saved in this browser. Assessment criteria and pass thresholds are configured in this workspace.</p><div class="divider"></div><p class="subtext">Reset removes changes saved in this browser and restores the starting records.</p><div style="margin-top:18px">${canAdmin()?button('Reset workspace data','reset-confirm','danger'):'<p class="inline-note">Management can restore the starting records.</p>'}</div></section></div>`;}
function openModal(title,subtitle,body,footer='',wide=false){if(!modal.open)modalReturnFocus=document.activeElement;modal.dataset.analytics=analyticsContext?'true':'false';modal.setAttribute('aria-labelledby','modal-title');modal.className=wide?'wide':'';modal.innerHTML=`<div class="modal-head"><div><h2 id="modal-title">${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!modal.open)modal.showModal();}
function closeModal(){modal.close();}
const field=(label,name,value='',type='text',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
function studentForm(id){if(!canManage())return;const s=state.students.find(s=>s.id===id);openModal(s?'Edit student':'A new journey starts here.','Student grouping is based on skill, not age.',`<form id="student-form" data-id="${s?.id||''}"><div class="form-grid">${field('Student name','name',s?.name||'','text','required maxlength="60" minlength="2"')}${field('Age','age',s?.age||10,'number','required min="5" max="80"')}<label class="field">Venue<select name="venue">${venues.filter(v=>canAdmin()||v===venues[0]).map(v=>`<option ${v===s?.venue?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Head coach<select name="coach">${coaches.filter(c=>c.role==='Head Coach'&&c.venue===(s?.venue||venues[0])).map(c=>`<option value="${c.id}" ${c.id===s?.coach?'selected':''}>${c.name}</option>`).join('')}</select></label>${field('Guardian email','email',s?.email||'','email','required')}${field('Guardian phone','phone',s?.phone||'','tel','required pattern="[0-9+ ()-]{7,20}"')}<label class="field">Training track<select name="track"><option ${s?.track==='Beginner'?'selected':''}>Beginner</option><option ${s?.track==='Intermediate'?'selected':''}>Intermediate</option></select></label><label class="field">Current curriculum level<input value="${s?.level||'Spark'}" disabled><small>${s?'Level changes require approved foundational review. Editing personal information does not promote students.':'New students begin at Spark. Use Day Zero to record prior experience for coach review.'}</small></label></div></form>`,button('Cancel','close-modal')+'<button class="button primary" type="submit" form="student-form">'+(s?'Save changes':'Add student')+'</button>');}
function skillModal(id,studentId){const k=state.skills.find(k=>k.id===+id),s=state.students.find(s=>s.id===studentId);if(!k)return;openModal(k.name,`${k.level} · Skill ${String(k.id).padStart(2,'0')} / 16`,`${notice('Review the skill target and record the five assessment criteria.')}<p class="subtext">${esc(k.description)}</p><div class="divider"></div><h3>Associated drill</h3><p class="subtext">${esc(k.drill)}</p><button class="text-button" data-action="drill:${k.id}">View drill instructions →</button><div class="divider"></div><h3>Coach checklist</h3>${k.criteria.map((c,i)=>`<div class="activity-row"><span class="pill neutral">0${i+1}</span>${esc(c)} · Yes / No</div>`).join('')}<div class="divider"></div><h3>Foundational prerequisites</h3><p class="subtext">${k.level==='Spark'?'Initial Spark foundation review.':`Coach review: check all ${levels[levels.indexOf(k.level)-1]} foundation badges and the reference skill targets.`} Individual skill assessment may proceed before all prerequisites are complete. Overall promotion remains subject to review.</p>${s?`<div class="divider"></div><h3>${esc(s.name)} · ${s.badges.includes(k.id)?'Badge completed':s.baseline?.includes(k.id)?'Baseline ability demonstrated':'Not yet completed'}</h3><p class="subtext">Current overall level: ${s.level}. This does not change when an individual badge is awarded.</p>`:''}`,button('Close','close-modal')+(canManage()?button('Edit skill content','skill-edit:'+k.id,'','edit'):'')+(s?button('Assess this skill','execute:'+s.id+':'+k.id,'primary','assessments'):''));}
function skillEdit(id){if(!canManage())return;const k=state.skills.find(k=>k.id===+id);openModal('Edit curriculum','Changes update the shared skill and drill library.',`<form id="skill-form" data-id="${k.id}"><div class="form-grid">${field('Skill name','name',k.name,'text','required maxlength="70"')}${field('Drill name','drill',k.drill,'text','required maxlength="70"')}<label class="field full">Description<textarea name="description" required>${esc(k.description)}</textarea></label><label class="field full">Drill instructions<textarea name="instructions" required>${esc(k.instructions)}</textarea></label>${k.criteria.map((c,i)=>field('Criterion '+(i+1),'criterion'+i,c,'text','required maxlength="150"')).join('')}</div></form>`,button('Cancel','close-modal')+'<button class="button primary" type="submit" form="skill-form">Save content</button>');}
function drillModal(id){const k=state.skills.find(k=>k.id===+id);openModal(k.drill,`${k.level} · ${k.name} · Coaching instructions`,`${notice('Follow the practice instructions and assessment points below.')}<div class="form-grid"><div class="video-placeholder" style="border-radius:9px">${icon('play')}<span>Practice video not added</span></div><div class="video-placeholder" style="border-radius:9px;background:#e9ede3">${icon('edit')}<span>Annotated video not added</span></div></div><div class="divider"></div><h3>Instructions</h3><p class="subtext">${esc(k.instructions)}</p><div class="divider"></div><h3>Coach checklist</h3>${k.criteria.map(c=>`<div class="activity-row">${icon('check')}${esc(c)}</div>`).join('')}`,button('Close','close-modal')+button('View skill','skill:'+k.id,'primary'));}
function execute(studentId='',skillId='',baseline=false,cycleId='',date=''){const ss=scoped();if(!ss.length){showToast('No students are assigned in this role. Add a student or switch to Management.');return;}const s=ss.find(s=>s.id===studentId)||ss[0];const k=state.skills.find(k=>k.id===+skillId)||state.skills[0];const prev=state.assessments.filter(a=>a.student===s.id&&a.skill===k.id);openModal(baseline?'Day Zero · Baseline assessment':'Record a skill assessment',baseline?'Capture prior experience as baseline evidence. No automatic foundation bypass.':'Five Yes/No criteria · Individual badge completion only.',`<form id="assessment-form" data-baseline="${baseline}" data-cycle="${cycleId}"><div class="form-grid"><label class="field">Student<select name="student" id="assessment-student" ${cycleId||baseline?'disabled':''}>${ss.map(x=>`<option value="${x.id}" ${x.id===s.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>${cycleId||baseline?`<input type="hidden" name="student" value="${s.id}">`:''}</label><label class="field">Skill<select name="skill" id="assessment-skill" ${cycleId||baseline?'disabled':''}>${state.skills.map(x=>`<option value="${x.id}" ${x.id===k.id?'selected':''}>${x.level} · ${esc(x.name)}</option>`).join('')}</select>${cycleId||baseline?`<input type="hidden" name="skill" value="${k.id}">`:''}</label>${field('Assessment date','date',date||today,'date',`required min="${s.joined}" max="${today}" ${cycleId?'readonly':''}`)}</div><div style="margin-top:20px">${notice(`Pass rule: at least ${state.settings.threshold} of 5 Yes responses.`)}</div><div id="assessment-criteria">${criteriaFields(k)}</div><label class="field" style="margin-top:20px">Coach remarks<textarea name="remarks" placeholder="Record strengths, observations and next steps…" required maxlength="1000"></textarea></label><div id="previous-attempts" style="margin-top:18px">${attemptSummary(prev)}</div></form>`,button('Cancel','close-modal')+'<button class="button primary" type="submit" form="assessment-form">Submit assessment</button>');}
function criteriaFields(k){return `<p class="inline-note" style="margin:16px 0"><strong>Skill target:</strong> ${esc(k.description)}<br>Record each of the five criteria below.</p>`+k.criteria.map((c,i)=>`<div class="criteria-row" role="group" aria-labelledby="criterion-label-${i}"><span id="criterion-label-${i}">${esc(c)}</span><div class="radio-group"><label><input type="radio" name="criterion${i}" value="yes" required>Yes</label><label><input type="radio" name="criterion${i}" value="no" required>No</label></div></div>`).join('');}
function attemptSummary(aa){return `<h3>Assessment history · ${aa.length} attempts</h3>${aa.length?aa.slice().reverse().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4).map(a=>`<div class="activity-row"><span>${dateLabel(a.date)}</span>${pill(a.outcome,a.outcome==='Passed'?'':'amber')}<span class="inline-note">${esc(a.remarks)}</span></div>`).join(''):'<p class="inline-note">No previous attempts for this student and skill.</p>'}`;}
function cycleForm(){if(!canManage())return;openModal('Plan an assessment cycle','One fixed date, with different skill modules for each student.',`<form id="cycle-form"><div class="form-grid">${field('Cycle name','name','','text','required maxlength="80"')}${field('Fixed assessment date','date',today,'date','required')}</div><div class="divider"></div><h3>Select students & assign modules</h3><p class="inline-note">Check each student, then select one or more modules. Hold Ctrl / Command to select multiple modules.</p>${scoped().map(s=>`<div class="module-row"><input type="checkbox" name="students" value="${s.id}" aria-label="Select ${esc(s.name)}"><div>${esc(s.name)}<small>${s.id} · ${s.level}</small></div><select name="modules-${s.id}" multiple aria-label="Modules for ${esc(s.name)}">${state.skills.map(k=>`<option value="${k.id}" ${k.level===s.level&&k.id%4===1?'selected':''}>${k.level} · ${esc(k.name)}</option>`).join('')}</select></div>`).join('')}<p id="cycle-error" style="color:var(--red);font-size:12px;margin-top:15px" role="alert"></p></form>`,button('Cancel','close-modal')+'<button class="button primary" type="submit" form="cycle-form">Create cycle</button>',true);}
function cycleDetails(id){const c=state.cycles.find(c=>c.id===id),ids=scoped().map(s=>s.id);openModal(c.name,`Fixed date: ${dateLabel(c.date)} · Student-specific modules`,`${notice('Assessment date is fixed for this cycle. Each student may have different assigned modules.')}<div class="stack">${c.assignments.filter(a=>ids.includes(a.student)).map(a=>`<section><h3>${esc(studentName(a.student))}</h3>${a.skills.map(id=>{const done=!!cycleOutcome(state,c,a.student,id);return `<div class="criteria-row"><span>${esc(skillName(id))} ${done?pill('Recorded'):''}</span>${button(done?'Reassess':c.date>today?'Preview & assess':'Record outcome','cycle-execute:'+c.id+':'+a.student+':'+id,'small')}</div>`;}).join('')}</section>`).join('')}</div>`,button('Close','close-modal'),true);}
function dayZero(){if(!canManage())return;if(!scoped().length){showToast('Add an assigned student before starting a baseline assessment.');return;}openModal('Day Zero · Find their starting point.','For students joining with previous badminton experience.',`${notice('Baseline results demonstrate abilities for coach review. They do not award curriculum badges, automatically promote students, or bypass foundational requirements.')}<form id="dayzero-form"><label class="field">1. Select student<select name="student">${scoped().map(s=>`<option value="${s.id}">${esc(s.name)} · ${s.level}</option>`).join('')}</select></label><h3 style="margin-top:22px">2. Choose relevant skills</h3><p class="inline-note">Conduct a separate Yes/No baseline assessment for each selected skill.</p>${state.skills.map(k=>`<div class="check-row"><input type="checkbox" name="skills" value="${k.id}" id="baseline-${k.id}"><label for="baseline-${k.id}">${esc(k.name)} ${pill(k.level)}</label></div>`).join('')}<p id="baseline-error" role="alert" style="color:var(--red);font-size:12px"></p></form>`,button('Cancel','close-modal')+'<button class="button primary" type="submit" form="dayzero-form">Start baseline assessment</button>');}
let baselineQueue=[];
function fitnessForm(){if(!fitnessStudent)return;openModal('Record intermediate fitness','Record results in the units shown.',`${notice('Results are for individual historical comparison. No automatic scoring, ranking or pass/fail standard is applied.')}<form id="fitness-form"><div class="form-grid">${field('Record date','date',today,'date',`required max="${today}" min="${state.students.find(s=>s.id===fitnessStudent).joined}"`)}${fitnessCategories.map((c,i)=>field(c.name+' ('+c.unit+')','value'+i,'','number',`required min="0.01" max="100000" step="0.01"`)).join('')}</div></form>`,button('Cancel','close-modal')+'<button class="button primary" type="submit" form="fitness-form">Save results</button>');}
function exportReport(){if(!canManage())return;const ss=selectedStudents(),aa=selectedAssessments(),rows=[['Student ID','Student','Venue','Head coach','Current level','Training track','Badges completed (all time)','Assessments in selected period','Passed in selected period','Needs practice in period'],...ss.map(s=>{const a=aa.filter(a=>a.student===s.id);return [s.id,s.name,s.venue,coachName(s.coach),s.level,s.track,s.badges.length,a.length,a.filter(x=>x.outcome==='Passed').length,a.filter(x=>x.outcome==='Needs Practice').length];})];const csv='\uFEFF'+rows.map(row=>row.map(v=>'"'+(/^[=+\-@\t\r]/.test(String(v))?"'"+String(v):String(v)).replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.download='VISIST-report-'+today+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);showToast('Filtered report exported as CSV.');}
function navigate(route,{replace=false}={}){
 const [requested,id,tab]=route.split('/');
 page=allowedPages(state.role).includes(requested)?requested:'dashboard';
 profileId=page==='students'&&scoped().some(s=>s.id===id)?id:'';
 profileTab=['progression','information','assessments','attendance'].includes(tab)?tab:'progression';
 if(page==='assessments')assessmentTab=['cycles','history','practice'].includes(id)?id:'cycles';
 const canonical=page+(profileId?'/'+profileId+'/'+profileTab:page==='assessments'&&assessmentTab!=='cycles'?'/'+assessmentTab:'');
 const target='#'+canonical;
 if(location.hash!==target)history[replace?'replaceState':'pushState'](null,'',target);
 studentPage=1;assessmentPage=1;render();window.scrollTo(0,0);
}
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1),{replace:true}));
window.addEventListener('popstate',()=>navigate(location.hash.slice(1),{replace:true}));
function syncDrawer(){const mobile=matchMedia('(max-width:700px)').matches;const drawer=$('#sidebar');if(!drawer)return;const open=mobile&&drawer.classList.contains('open');drawer.inert=mobile&&!open;$('.main-shell').inert=open;}
window.addEventListener('resize',syncDrawer);
function closeDrawer(){const drawer=$('#sidebar');if(!drawer?.classList.contains('open'))return;drawer.classList.remove('open');syncDrawer();const trigger=$('[data-action=menu]');trigger?.setAttribute('aria-expanded','false');trigger?.focus();}
document.addEventListener('keydown',event=>{if(event.key==='Tab'&&$('#sidebar')?.classList.contains('open')&&matchMedia('(max-width:700px)').matches){const controls=[...$('#sidebar').querySelectorAll('button,a')],first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}if(event.key==='Escape'&&!modal.open){closeDrawer();$('.global-search')?.classList.remove('search-open');$('#search-results').innerHTML='';}});
document.addEventListener('click',event=>{if(!event.target.closest('.global-search, [data-action=search-open]')){const results=$('#search-results');if(results)results.innerHTML='';$('.global-search')?.classList.remove('search-open');}const link=event.target.closest('a[href^="#"]:not([data-action])');if(link){event.preventDefault();closeDrawer();navigate(link.getAttribute('href').slice(1));return;}const control=event.target.closest('[data-action]');if(!control)return;const [action,a,b,c]=control.dataset.action.split(':');switch(action){case'chart-period':{const bucket=progressionBuckets()[+a];if(bucket)analyticsRecords({type:'period',start:bucket.start,end:bucket.end});break;}case'chart-outcome':if(['Passed','Needs Practice'].includes(a))analyticsRecords({type:'outcome',outcome:a});break;case'analytics-prev':analyticsRecords(analyticsContext,analyticsPage-1);break;case'analytics-next':analyticsRecords(analyticsContext,analyticsPage+1);break;case'analytics-back':analyticsRecords(analyticsContext,analyticsPage);break;case'chart-level':if([...levels,'All levels'].includes(a)){filters.level=filters.level===a?'All levels':a;studentPage=1;render();requestAnimationFrame(()=>[...document.querySelectorAll('[data-action]')].find(el=>el.dataset.action==='chart-level:'+a)?.focus({preventScroll:true}));}break;case'chart-venue':if([...venues,'All venues'].includes(a)){filters.venue=filters.venue===a?'All venues':a;studentPage=1;render();requestAnimationFrame(()=>document.querySelector('[data-action="chart-venue:'+CSS.escape(a)+'"]')?.focus());}break;case'chart-clear':filters.venue='All venues';filters.level='All levels';studentPage=1;render();document.querySelector('[data-filter="venue"]')?.focus();break;case'chart-students':scopedStudentsModal();break;case'fitness-history':fitnessHistory(+a);break;case'fitness-point':updateChartReadout(control);break;case'collection':event.preventDefault();$('#collection-'+a)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});break;case'menu':{const drawer=$('#sidebar'),open=drawer.classList.toggle('open');control.setAttribute('aria-expanded',String(open));syncDrawer();if(open)drawer.querySelector('.drawer-close').focus();break;}case'menu-close':closeDrawer();break;case'goto':navigate(a);break;case'demo-date':demoDateForm();break;case'search-open':$('.global-search').classList.toggle('search-open');$('#global-search').focus();break;case'close-modal':closeModal();break;case'notifications':state.notificationsRead=true;persist();openModal('Academy updates','Recent academy activity',`<div class="notification-list">${visibleActivities().slice(0,8).map(x=>`<article>${esc(x.text)}<small>${dateLabel(x.date)}</small></article>`).join('')}</div>`,button('Done','close-modal'));$('.notification-dot')?.remove();break;case'student-add':studentForm();break;case'student-edit':studentForm(a);break;case'profile':if(!scoped().some(s=>s.id===a))return;closeModal();navigate('students/'+a+'/progression');break;case'students-back':navigate('students');break;case'profile-tab':navigate('students/'+profileId+'/'+a);break;case'history-prev':assessmentPage--;render();break;case'history-next':assessmentPage++;render();break;case'page-prev':studentPage--;render();break;case'page-next':studentPage++;render();break;case'skill':skillModal(a,b);break;case'skill-edit':skillEdit(a);break;case'drill':drillModal(a);break;case'execute':baselineQueue=[];execute(a,b);break;case'cycle-add':cycleForm();break;case'cycle':cycleDetails(a);break;case'cycle-execute':startCycle(a,b,c);break;case'cycle-start':{const cycle=state.cycles.find(x=>x.id===a);changeDemoDate(cycle.date);baselineQueue=[];execute(b,c,false,a,cycle.date);break;}case'assessment-tab':navigate('assessments/'+a);break;case'assessment-detail':{const r=state.assessments.find(x=>x.id===a);if(!r||!scoped().some(s=>s.id===r.student))return;openModal('Assessment details',`${studentName(r.student)} · ${skillName(r.skill)} · ${dateLabel(r.date)}`,`${r.baseline?notice('Day Zero baseline evidence only. No curriculum badge or promotion was applied.'):''}${pill(r.outcome,r.outcome==='Passed'?'':'amber')}<div class="divider"></div>${r.answers.map((yes,i)=>`<div class="criteria-row"><span>${esc((r.criteria||state.skills.find(k=>k.id===r.skill).criteria)[i])}</span>${pill(yes?'Yes':'No',yes?'':'amber')}</div>`).join('')}<div class="divider"></div><p class="inline-note">Recorded pass threshold: ${r.threshold??4}/5. Criteria are preserved as recorded.</p><h3>Coach remarks</h3><p class="subtext">${esc(r.remarks)}</p><p class="inline-note" style="margin-top:15px">Recorded by ${coachName(r.coach)}.</p>`,button('Close','close-modal')+(analyticsContext?button('Back to assessments','analytics-back'):''));break;}case'dayzero':dayZero();break;case'baseline-next':{const next=baselineQueue.shift();if(next)execute(a,next,true);else{closeModal();navigate('students/'+a+'/progression');}break;}case'practice-list':navigate('assessments/practice');break;case'coach':{const co=coaches.find(x=>x.id===+a),ss=coachStudents(co);openModal(co.name,`${co.role} · ${co.venue}`,ss.length?table(['STUDENT','LEVEL','BADGES'],ss.map(s=>`<tr><td>${person(s)}</td><td>${pill(s.level)}</td><td>${s.badges.length} / 16</td></tr>`)):empty(),button('Close','close-modal'),true);break;}case'attendance-all':document.querySelectorAll('[data-attendance]').forEach(x=>x.value='Present');captureSessionDraft();showToast('All students marked present. Save the session to keep changes.');break;case'attendance-save':saveAttendance();break;case'fitness-add':fitnessForm();break;case'export':exportReport();break;case'reset-confirm':if(!canAdmin())return;openModal('Reset workspace data?','This removes changes saved in this browser.',`<p class="subtext">The starting records will be restored. This action cannot be undone.</p>`,button('Keep changes','close-modal')+button('Reset workspace','reset','danger'));break;case'reset':if(!canAdmin())return;reset();today=state.demoDate;attendanceDate=today;attendanceVenue=venues[0];studentSearch='';studentSort='name';toolSkill='All skills';closeModal();filters={venue:'All venues',level:'All levels',range:'90'};navigate('dashboard');showToast('Starting workspace records restored.');break;}});
document.addEventListener('change',event=>{const el=event.target;if(el.matches('[data-filter]')){filters[el.dataset.filter]=el.value;studentPage=1;if(el.dataset.filter==='level')toolSkill='All skills';render();}else if(el.id==='role-switch'){state.role=el.value;persist();profileId='';studentSearch='';toolSkill='All skills';filters={venue:'All venues',level:'All levels',range:'90'};attendanceVenue=venues[0];navigate('dashboard');showToast('Switched to '+state.role+' view.');}else if(el.matches('#student-form [name=venue]')){const select=$('#student-form [name=coach]');select.innerHTML=coaches.filter(c=>c.role==='Head Coach'&&c.venue===el.value).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');}else if(el.id==='student-sort'){studentSort=el.value;render();}else if(el.id==='tool-skill'){toolSkill=el.value;render();}else if(el.id==='attendance-venue'){attendanceVenue=el.value;render();}else if(el.id==='attendance-session'){attendanceSession=el.value;render();}else if(el.id==='attendance-date'){if(el.value)attendanceDate=el.value;render();}else if(el.matches('[data-attendance]'))captureSessionDraft();else if(el.id==='fitness-student'){fitnessStudent=el.value;render();}else if(el.id==='assessment-student'||el.id==='assessment-skill'){const form=$('#assessment-form'),student=form.elements.student.value,skill=+form.elements.skill.value,k=state.skills.find(k=>k.id===skill);form.elements.date.min=state.students.find(s=>s.id===student).joined;$('#assessment-criteria').innerHTML=criteriaFields(k);$('#previous-attempts').innerHTML=attemptSummary(state.assessments.filter(a=>a.student===student&&a.skill===skill));}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='session-notes'){captureSessionDraft();}else if(el.id==='student-search'){const start=el.selectionStart;studentSearch=el.value;studentPage=1;render();const replacement=$('#student-search');replacement.focus();replacement.setSelectionRange(start,start);}else if(el.id==='global-search'){const q=el.value.trim().toLowerCase();$('#search-results').innerHTML=q?`<div class="search-results">${[...scoped().filter(s=>(s.name+' '+s.id).toLowerCase().includes(q)).slice(0,4).map(s=>`<button class="search-result" data-action="profile:${s.id}">${esc(s.name)}<small>${s.id} · ${s.venue}</small></button>`),...state.skills.filter(s=>s.name.toLowerCase().includes(q)).slice(0,3).map(s=>`<button class="search-result" data-action="skill:${s.id}">${esc(s.name)}<small>${s.level} · Skill</small></button>`)].join('')||empty('No matching results','Try a student name or badminton skill.')}</div>`:'';}});
function updateDrills(){const ids=[...document.querySelectorAll('[data-attendance]')].filter(el=>el.value==='Present').map(el=>el.dataset.attendance);$('#session-drills').innerHTML=sessionDrills(attendanceStudents().filter(s=>ids.includes(s.id)));}
function saveAttendance(){
 const controls=[...document.querySelectorAll('[data-attendance]')];
 if(!controls.length){showToast('No students in this session. Choose another venue.');return;}
 const statuses=Object.fromEntries(controls.map(el=>[el.dataset.attendance,el.value]));
 const hasExisting=state.attendance.some(a=>a.date===attendanceDate&&a.session===attendanceSession&&controls.some(el=>el.dataset.attendance===a.student));
 if(!hasExisting&&controls.every(el=>el.value==='Unmarked')){showToast('Mark at least one student before saving.');return;}
 try {saveSession(state,{students:attendanceStudents(),date:attendanceDate,session:attendanceSession,notes:$('#session-notes').value,statuses});}
 catch(error){showToast(error.message);return;}
 delete state.sessionDrafts[sessionKey()];
 activity(`${attendanceVenue} session saved for ${controls.filter(x=>x.value!=='Unmarked').length} students`,'attendance',attendanceStudents().map(s=>s.id));
 save('Attendance and session observations saved.');
}

function coachStudents(coach){return scoped().filter(s=>coach.role==='Head Coach'?s.coach===coach.id:s.venue===coach.venue&&s.level==='Spark');}
function visibleActivities({filtered=false}={}){const ids=new Set((filtered?selectedStudents():scoped()).map(s=>s.id));const restricted=filtered&&(filters.venue!=='All venues'||filters.level!=='All levels');return state.activities.filter(a=>canAdmin()&&!restricted||[...(a.students||[]),a.student].some(id=>ids.has(id)));}
function focusSkill(student){const failed=needsPractice(state,{student:student.id,through:today})[0];return state.skills.find(k=>k.id===failed?.skill)||state.skills.find(k=>k.level===student.level&&!student.badges.includes(k.id));}
function studentAttention(student){
 const failed=needsPractice(state,{student:student.id,through:today}),modules=pending(student);
 return `<section class="card card-pad profile-attention"><h2>Next coaching steps</h2>${failed.length?failed.map(a=>`<div class="criteria-row"><div><strong>${esc(skillName(a.skill))}</strong><p class="subtext">${state.assessments.filter(x=>!x.baseline&&x.student===student.id&&x.skill===a.skill&&x.outcome==='Needs Practice'&&x.date<=today).length} unsuccessful attempt(s) · Latest ${dateLabel(a.date)}</p></div>${button('Reassess','execute:'+student.id+':'+a.skill,'small')}</div>`).join(''):'<p class="subtext">No unresolved unsuccessful skill assessments.</p>'}${modules.length?`<p class="inline-note" style="margin-top:12px">${modules.length} assigned module(s) pending.</p>`+modules.map(m=>`<div class="criteria-row"><span>${esc(skillName(m.skill))} · ${dateLabel(m.cycle.date)}</span>${button('Open cycle','cycle:'+m.cycle.id,'small')}</div>`).join(''):''}</section>`;
}
function sessionKey(){return [state.role,attendanceVenue,attendanceDate,attendanceSession].join('|');}
function captureSessionDraft(){
 state.sessionDrafts[sessionKey()]={statuses:Object.fromEntries([...document.querySelectorAll('[data-attendance]')].map(el=>[el.dataset.attendance,el.value])),notes:$('#session-notes').value};
 const stored=persist();updateDrills();if($('#session-dirty'))$('#session-dirty').textContent=stored?'Unsaved draft · save to update dashboards.':'Unsaved draft · browser storage is unavailable; keep this session open.';
}
function changeDemoDate(date){
 if(!validDate(date))return false;
 today=state.demoDate=date;attendanceDate=date;persist();return true;
}
function demoDateForm(){openModal('Workspace date','Reporting and session defaults use this workspace date.',`<form id="demo-date-form">${field('Workspace date','date',today,'date','required')}<p class="inline-note" style="margin-top:12px">Use an assessment cycle’s fixed date when recording its results. Historical results remain saved; changing the reporting date does not revoke earned badges or promote students.</p></form>`,button('Cancel','close-modal')+'<button class="button primary" type="submit" form="demo-date-form">Use workspace date</button>');}
function startCycle(id,student,skill){
 const cycle=state.cycles.find(c=>c.id===id);if(!cycle)return;
 if(cycle.date>today){openModal('Preview this assessment date',`This cycle is fixed for ${dateLabel(cycle.date)}.`,notice('Continue to set the workspace date to this cycle’s date. Recorded outcomes will then appear in the dashboard and reporting period.'),button('Cancel','close-modal')+button('Use '+dateLabel(cycle.date)+' & assess','cycle-start:'+id+':'+student+':'+skill,'primary'));return;}
 baselineQueue=[];execute(student,skill,false,id,cycle.date);
}

document.addEventListener('submit',event=>{const form=event.target;if(!['student-form','skill-form','assessment-form','cycle-form','dayzero-form','fitness-form','settings-form','demo-date-form'].includes(form.id))return;event.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);const blankField=[...form.querySelectorAll('input[required][type=text], textarea[required]')].find(el=>!el.value.trim());if(blankField){blankField.setCustomValidity('Please enter a value, not just spaces.');blankField.reportValidity();blankField.addEventListener('input',()=>blankField.setCustomValidity(''),{once:true});return;}switch(form.id){case'demo-date-form':if(!changeDemoDate(data.get('date'))){showToast('Choose a valid workspace date.');return;}closeModal();save('Workspace date updated.');break;case'student-form':{if(!canManage())return;const values={name:data.get('name').trim(),age:+data.get('age'),venue:data.get('venue'),coach:+data.get('coach'),email:data.get('email').trim(),phone:data.get('phone').trim(),track:data.get('track')};if(!coaches.some(c=>c.id===values.coach&&c.role==='Head Coach'&&c.venue===values.venue)||(!canAdmin()&&(values.coach!==1||values.venue!==venues[0]))){showToast('Choose the head coach assigned to this venue.');return;}if(values.name.length<2){showToast('Enter a student name with at least two characters.');return;}const existing=state.students.find(s=>s.id===form.dataset.id);if(existing)Object.assign(existing,values);else{const next=Math.max(0,...state.students.map(s=>+s.id.slice(2)))+1;state.students.push({...values,id:'VS'+String(next).padStart(3,'0'),level:'Spark',badges:[],baseline:[],joined:today});}activity(`${values.name}'s student record ${existing?'updated':'created'}`,'students',existing?.id||state.students.at(-1).id);closeModal();const stored=persist();navigate('students/'+(existing?.id||state.students.at(-1).id)+'/information');showToast(stored?(existing?'Student information updated.':'Student added. Their journey begins at Spark.'):'Student recorded for this session only; browser storage is unavailable.');break;}case'skill-form':{if(!canManage())return;const skill=state.skills.find(k=>k.id===+form.dataset.id);Object.assign(skill,{name:data.get('name').trim(),drill:data.get('drill').trim(),description:data.get('description').trim(),instructions:data.get('instructions').trim(),criteria:Array.from({length:5},(_,i)=>data.get('criterion'+i).trim())});closeModal();save('Curriculum updated across the workspace.');break;}case'settings-form':state.settings.threshold=+data.get('threshold');save('Pass threshold saved.');break;case'cycle-form':{if(!canManage())return;const ids=data.getAll('students');if(!ids.length){$('#cycle-error').textContent='Select at least one student.';return;}const assignments=ids.map(id=>({student:id,skills:data.getAll('modules-'+id).map(Number)}));if(assignments.some(a=>!a.skills.length)){$('#cycle-error').textContent='Assign at least one module to every selected student.';return;}if(!validDate(data.get('date'))||assignments.some(a=>data.get('date')<state.students.find(s=>s.id===a.student).joined)){$('#cycle-error').textContent='The cycle date must be on or after enrolment for every selected student.';return;}state.cycles.push({id:crypto.randomUUID(),name:data.get('name').trim(),date:data.get('date'),assignments});activity(`${data.get('name')} scheduled for ${ids.length} students`,'assessment',ids);closeModal();save('Assessment cycle created with individual modules.');break;}case'dayzero-form':{const ids=data.getAll('skills').map(Number);if(!ids.length){$('#baseline-error').textContent='Choose at least one skill for baseline assessment.';return;}baselineQueue=ids;execute(data.get('student'),baselineQueue.shift(),true);break;}case'assessment-form':{const student=data.get('student'),skill=+data.get('skill'),s=state.students.find(s=>s.id===student);if(!scoped().some(x=>x.id===student))return;const answers=Array.from({length:5},(_,i)=>data.get('criterion'+i)==='yes'),count=answers.filter(Boolean).length,baseline=form.dataset.baseline==='true';const wasEarned=s.badges.includes(skill);let r;
 try{r=recordAssessment(state,{student,skill,date:data.get('date'),answers,remarks:data.get('remarks'),coach:state.role==='Assistant Coach'?4:state.role==='Head Coach'?1:s.coach,baseline,cycleId:form.dataset.cycle||null});}catch(error){showToast(error.message);return;}
 const outcome=r.outcome;activity(`${s.name}: ${skillName(skill)} — ${outcome}${baseline?' (Day Zero baseline)':''}`,outcome==='Passed'?'badge':'practice',student);const stored=persist();render();openModal(baseline?'Baseline recorded':'Assessment saved',`${s.name} · ${skillName(skill)}`,`<div class="result-box ${!baseline&&outcome==='Passed'&&!wasEarned?'badge-celebration':''} ${outcome==='Needs Practice'?'warning':''}">${!baseline&&outcome==='Passed'&&!wasEarned?`<div class="celebration-emblem">${emblem(state.skills.find(k=>k.id===skill).level,true)}</div><div class="eyebrow">NEW SKILL BADGE COLLECTED</div>`:''}<div class="eyebrow">${baseline?'BASELINE RESULT':'ASSESSMENT OUTCOME'}</div><h2>${outcome}</h2><p>${count} of 5 Yes responses · Pass threshold: ${state.settings.threshold}/5</p></div><p class="subtext">${baseline?'Demonstrated abilities are saved as separate baseline evidence. Proposed starting point: retain '+s.level+' while the head coach reviews foundational requirements and the demonstrated skills. No curriculum badges or promotion have been applied.':outcome==='Passed'?'The individual skill badge is recorded. Overall level remains '+s.level+' pending foundational and academy-approved progression review.':'The attempt is visible in the assessment history. Continue guided practice and reassess when ready.'}</p><div class="divider"></div><h3>Coach remarks</h3><p class="subtext">${esc(r.remarks)}</p>${baseline?`<p class="inline-note" style="margin-top:15px">${baselineQueue.length} baseline skill(s) remaining. Demonstrated so far: ${esc((s.baseline||[]).map(skillName).join(', ')||'None yet')}.</p>`:''}`,baseline?button(baselineQueue.length?'Assess next baseline skill':'Review proposed starting point','baseline-next:'+student,'primary'):button('View student progression','profile:'+student,'primary')+(r.cycleId?button('Return to cycle','cycle:'+r.cycleId):''));showToast(stored?'Assessment saved successfully.':'Assessment recorded for this session only; browser storage is unavailable.');break;}case'fitness-form':state.fitness.push({id:'F'+Date.now(),student:fitnessStudent,date:data.get('date'),values:fitnessCategories.map((_,i)=>+data.get('value'+i))});activity(`Intermediate fitness recorded for ${studentName(fitnessStudent)}`,'fitness',fitnessStudent);closeModal();save('Fitness results saved to student history.');break;}});
modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
document.addEventListener('pointerover',event=>updateChartReadout(event.target));
document.addEventListener('focusin',event=>updateChartReadout(event.target));
document.addEventListener('keydown',event=>{const control=event.target.closest?.('svg [role="button"]');if(control&&(event.key==='Enter'||event.key===' ')){event.preventDefault();control.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
modal.addEventListener('close',()=>{analyticsContext=null;const target=modalReturnFocus;modalReturnFocus=null;if(target?.isConnected)target.focus({preventScroll:true});});
navigate(location.hash.slice(1)||'dashboard',{replace:true});
if(storageError)showToast(storageError);
